WITH base AS (SELECT *, LENGTH(txn_type) AS txn_type_length, COALESCE(merchant, 'N/A') AS merchant_clean FROM transactions WHERE merchant IS NOT NULL AND txn_time > DATE '2023-10-31') SELECT p.status, s.txn_type, COUNT(*) AS cnt, ROUND(SUM(s.txn_type_length), 2) AS total_txn_type_length, MAX(s.amount) AS max_amount FROM base s INNER JOIN accounts p ON s.account_id = p.id GROUP BY p.status, s.txn_type ORDER BY cnt NULLS FIRST
